UPDATE gacha_user_pity
SET ssr_count = #{ssrCount}, sr_count = #{srCount},
    total_count = #{totalCount}, ssr_total = #{ssrTotal}
WHERE user_id = #{userId} AND pool_id = #{poolId}

mapper.select:
SELECT id, batch_no, user_id, pool_id, card_id, card_name,
       rarity, is_up, draw_index, is_pity, cost, created_at
FROM gacha_draw_record
WHERE user_id = #{userId}
AND pool_id = #{poolId}
ORDER BY created_at DESC, draw_index DESC
LIMIT #{limit}

SELECT id, user_id, card_id, pool_id, card_name, rarity, count, first_at, updated_at
FROM gacha_user_card
WHERE user_id = #{userId}
AND rarity = #{rarity}
ORDER BY FIELD(rarity, 'SSR', 'SR', 'R', 'N'), first_at DESC

SELECT id, user_id, card_id, pool_id, card_name, rarity, count, first_at, updated_at
FROM gacha_user_card
WHERE user_id = #{userId} AND card_id = #{cardId}
